import{_ as i,l,o as e,c as n,v as t,p as s,x as r,d as h,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"BARC 开口刻蚀","description":"","frontmatter":{"title":"BARC 开口刻蚀","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/barc-open-etch.md","filePath":"litho/barc-open-etch.md","lastUpdated":1789023840000}'),p={name:"litho/barc-open-etch.md"};function A(B,a,_,C,m,b){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="barc-开口刻蚀" tabindex="-1">BARC 开口刻蚀 <a class="header-anchor" href="#barc-开口刻蚀" aria-label="Permalink to &quot;BARC 开口刻蚀&quot;">​</a></h1><div class="epigraph"><p>胶上的窗只开到 BARC 顶；转印还要把抗反射层打开。开口刻蚀吃 CD、吃侧壁，是 OPC 回环的第一段等离子体。</p><footer>—— 对照 BARC open etch；接续 [驻波与 BARC](/litho/standing-wave-barc)、[刻蚀偏置](/litho/cdu-etch-bias)</footer></div><p><a href="/litho/backside-bevel-clean">上一课</a>把片夹干净。缺口回到正面：显影停在胶，BARC / SOG 仍盖着衬底。本课钉开口刻蚀，不把主衬底刻蚀写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>BARC 为光学存在，对刻蚀是必须打穿的膜。开口偏置进入 <a href="/litho/etch-in-opc">刻蚀进 OPC</a> 的第一项。选择比不足会打穿衬底或削胶顶；过刻侧蚀吃线宽。把 AEI–ADI 差全写成主刻蚀，会漏掉这一薄层。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>短等离子体，化学依 BARC 是有机还是含硅（SOG）。终点：光学或时间。三层：先开 SOG 再开 SOC，每段选择比不同。CD 量测应分 ADI、BARC-open 后、主刻后，才能把偏置拆开。</p>',7)),(e(),s(d,null,{default:r(()=>[c(o,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADI%5B%22ADI%20%E8%83%B6%E7%AA%97%22%5D%20--%3E%20BO%5B%22BARC%20%2F%20SOG%20%E5%BC%80%E5%8F%A3%22%5D%0A%20%20BO%20--%3E%20SOC%5B%22%E5%8F%AF%E9%80%89%20SOC%20%E5%BC%80%E5%8F%A3%22%5D%0A%20%20SOC%20--%3E%20MAIN%5B%22%E4%B8%BB%E5%88%BB%E8%9A%80%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><span class="marginnote">有机 BARC 常用氧化性气体，胶也会被吃。开口时间窗口窄，是随机残膜与过刻之间的缝。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>各向异性开口尽量保侧壁，但仍有微观侧蚀。驻波造成的胶脚在开口时可能被修掉或被放大。与去渣的差别：去渣清残胶，开口打穿设计存在的底层。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课胶去除：图形已经转到硬掩模或衬底之后，胶本身要剥离。开口时胶还在当掩模。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>BARC 开口是光学层的等离子体代价，偏置要单独量。</li><li>三层开口是一条链，不是一次刻蚀。</li><li>出处：BARC / trilayer 开口通识；刻蚀偏置课。</li></ul>',7))])}const E=i(p,[["render",A]]);export{f as __pageData,E as default};
